#!/usr/bin/env python3
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]; DATE='2026-11-02'; DISPLAY='November 2, 2026'
topics=[('task-brief-01','Keep a task brief tied to the approved request','task briefs','the client success manager'),('handover-note-02','Write a handover note the next assistant can use','handover notes','the client success manager'),('inbox-triage-03','Triage an executive inbox with bounded access','inbox triage','the executive or chief of staff'),('calendar-04','Resolve a calendar conflict without taking the decision','calendar coordination','the executive or chief of staff'),('meeting-notes-05','Turn meeting notes into owned actions','meeting notes','the meeting chair'),('document-format-06','Control a document format change through review','document format changes','the operations manager'),('vendor-followup-07','Track a vendor follow-up without losing the promise','vendor follow-up','the operations manager'),('travel-brief-08','Prepare a travel brief with a named fallback','travel briefs','the travel coordinator'),('research-brief-09','Prepare a research brief from approved sources','research briefs','the executive or research lead'),('access-review-10','Prepare an access review without changing permissions','access reviews','the security or operations owner'),('quality-sample-11','Run a quality sample without vanity metrics','quality sampling','the quality lead'),('continuity-12','Test assistant coverage before leave','coverage continuity','the operations manager')]
research=[('task-brief-completeness-01','task brief completeness'),('handover-reliability-02','handover note reliability'),('access-review-coverage-03','access review coverage'),('quality-sample-signal-04','quality sample signal'),('continuity-coverage-05','coverage continuity')]
sources=[{'name':'NIST Cybersecurity Framework','url':'https://www.nist.gov/cyberframework','note':'Official risk-management framework consulted for general research context.'},{'name':'NIST Privacy Framework','url':'https://www.nist.gov/privacy-framework','note':'Official privacy risk-management framework consulted for general research context.'},{'name':'Cybersecurity and Infrastructure Security Agency','url':'https://www.cisa.gov/','note':'Public infrastructure security guidance.'},{'name':'International Labour Organization','url':'https://www.ilo.org/','note':'International labor standards context.'},{'name':'U.S. Department of Labor','url':'https://www.dol.gov/','note':'U.S. labor guidance and worker protections.'},{'name':'U.S. Small Business Administration','url':'https://www.sba.gov/','note':'Small-business operations guidance.'}]
def paras(focus,owner,stop):
 return [f"A {focus} case without a named owner can move through the queue while nobody can say what was checked. The {owner} keeps the decision and any commitment that changes money, access, policy, or a client promise. The assistant may organize the record, compare sources, and route exceptions.",f"The approved source is named before work starts. The record shows the source date, reviewer, next action, and evidence that closed the case. Keep restricted information in the approved system.",f"The stop condition is: {stop}. When it appears, preserve the facts and route the exact missing item to the {owner}.",f"Start with the oldest unresolved item. At handoff, name what moved, what is waiting, who owns the next check, and which evidence is missing.",f"A sent message or uploaded file proves activity, not an approved task or client-visible result. Verification belongs in the destination record."]
blogs=[]; details={}
for slug,title,focus,owner in topics:
 p=paras(focus,owner,'the request changes money, access, policy, a legal obligation, or a client promise')
 blog_slug=f'outsourcingassistant-{slug}-2026-11-02'
 sections=[{'heading':'Why the '+focus+' needs its own control','paragraphs':[p[0],p[1]]},{'heading':'What the record must show','paragraphs':[p[4],p[1]]},{'heading':'Where the work stops','paragraphs':[p[2],p[3]]},{'heading':'The daily routine','paragraphs':[p[3],p[4]]},{'heading':'Verify and close','paragraphs':[p[4],p[2]]},{'heading':'The monthly review','paragraphs':['Sample normal, exception, and reopened records against the same rule. End with one process change, one owner, and one check date.']}]
 blogs.append({'slug':blog_slug,'title':title,'excerpt':f'A source-bounded outsourced assistant operations guide for executives and operations teams, focused on {focus} and bounded by honest evidence.','minutes':6,'takeaway':p[0],'sections':sections,'faqs':[{'q':f'What should the team check first on {focus}?','a':p[1]},{'q':'Which decisions stay with the owner?','a':p[2]},{'q':'How should quality be reviewed?','a':'Sample normal, exception, and reopened records against the same written rule.'}],'published':DATE,'updated':DATE,'image':{'url':f'/daily02/outsourcingassistant/{blog_slug}.png','alt':f'Title-overlaid editorial thumbnail for {title}'},'citations':sources,'internalLinks':[{'label':'Services','href':'/services'},{'label':'Contact','href':'/contact-us'}],'cta':{'label':'Plan the role','href':'/contact-us'}})
 details[blog_slug]={'updated':DATE,'takeaways':[p[0],p[3],p[2]],'sections':sections,'sources':sources,'serviceHandoff':{'href':'/services','label':'See the related service','body':'Use the evidence and boundary language in the role brief.'}}
rs=[]
for slug,focus in research:
 full=f'outsourcingassistant-{slug}-2026-11-02'; p=paras(focus,'the client success manager','the source is missing, records disagree, or the request changes access, pay, or a client commitment')
 heads=['Research question and scope','Population and unit of analysis','Definitions that make the measure reproducible','Evidence standard and data dictionary','Sampling and collection','Analysis and reporting','Limitations and sources of error','Review cadence and next action','Data quality checks','Privacy, access, and retention','Worked example of the record','What would change the answer','Reporting package and handoff']
 sections=[{'heading':h,'paragraphs':[p[i%len(p)],p[(i+2)%len(p)]]} for i,h in enumerate(heads)]
 body=[]
 for s in sections: body += ['## '+s['heading']]+s['paragraphs']
 body += ['## Sources']+[f"- [{x['name']}]({x['url']}) — checked {DISPLAY}." for x in sources]
 rs.append({'slug':full,'title':f'How complete is the evidence in the {focus} record?','excerpt':f'A repeatable measurement protocol for {focus} in outsourced assistant operations, with definitions, sampling, limits, and reporting.','published':DATE,'updated':DATE,'cluster':'Evidence Quality','image':{'url':f'/daily02/outsourcingassistant/{full}.png','alt':f'Title-overlaid research graphic for How complete is the evidence in the {focus} record?'},'headlineStat':'6 authoritative sources and 13 protocol sections.','methodology':f'A repeatable measurement protocol for {focus} in outsourced assistant operations.','keyStats':['6 public sources reviewed','13 protocol sections',f'{DISPLAY} verification date'],'takeaways':[p[0],p[1],p[4]],'sections':sections,'faqs':[{'q':'What does the protocol establish?','a':p[0]},{'q':'What are the limits?','a':p[4]}],'sources':sources,'related':['/research','/blog'],'body':body,'serviceHandoff':{'heading':'Service handoff','href':'/services','label':'See the related service','paragraphs':['Use the evidence and boundary language in the role brief.']}})
(ROOT/'app/nov02-blog.ts').write_text('import type { BlogPost } from \'./data\';\n\nexport const nov02BlogBatch: BlogPost[] = '+json.dumps(blogs,indent=2,ensure_ascii=False)+';\n')
(ROOT/'app/nov02-research.ts').write_text('import type { ResearchPost } from \'./fleet-content\';\n\nexport const nov02ResearchBatch: ResearchPost[] = '+json.dumps(rs,indent=2,ensure_ascii=False)+';\n')
p=ROOT/'app/data.ts'; t=p.read_text()
if 'nov02BlogBatch' not in t:
 t=t.replace("import { oct28BlogBatch } from './oct28-blog';","import { oct28BlogBatch } from './oct28-blog';\nimport { nov02BlogBatch } from './nov02-blog';")
 t=t.replace('blogPosts.push(...oct28BlogBatch,','blogPosts.push(...nov02BlogBatch, ...oct28BlogBatch,')
 p.write_text(t)
p=ROOT/'app/fleet-content.ts'; t=p.read_text()
if 'nov02ResearchBatch' not in t:
 t=t.replace("import { oct28ResearchBatch } from './oct28-research';","import { oct28ResearchBatch } from './oct28-research';\nimport { nov02ResearchBatch } from './nov02-research';")
 t=t.replace('  ...oct28ResearchBatch,','  ...nov02ResearchBatch,\n  ...oct28ResearchBatch,')
 p.write_text(t)
print('generated',len(blogs)+len(rs))
